#!/usr/bin/env python3
"""Writes tests/fixtures/golden.json from the research script docs/research/data/v1-baseline.py.

The golden file locks the TypeScript calculator to the research figures: golden.test.ts checks
every case. Regenerate only when the research itself changes, and review the diff:

    python3 -I tests/fixtures/generate_golden.py

All amounts are whole sen.
"""
import importlib.util
import json
import os
from decimal import Decimal as D

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
spec = importlib.util.spec_from_file_location("v1", os.path.join(ROOT, "docs", "research", "data", "v1-baseline.py"))
v1 = importlib.util.module_from_spec(spec)
spec.loader.exec_module(v1)

STATUSES = ["single", "married-spouse-not-working", "married-spouse-working", "divorced-or-widowed"]
INPUTS = ["salary", "age", "year", "status", "children", "skbbkOptedOut", "wifeDeduction"]
OUTPUTS = ["epfEmployee", "epfEmployer", "socsoEmployee", "socsoEmployer", "eisEmployee", "eisEmployer",
           "annualTax", "pcb", "takeHome", "employerCost", "zakatAnnual", "zakatMonthly",
           "zakatRebateAtFiling", "zakatNotRecoverable"]


def sen(x):
    return int((D(str(x)) * 100).to_integral_value())


def case(salary, age, year, status, children, opted_out, wife):
    b = v1.breakdown(salary, age=age, year=year, opted_out=opted_out, status=status, children=children)
    kids = 0 if v1.CATEGORY[status] == 1 else children
    z = v1.zakat_annual(salary, b["epf"], year, 2, kids, wife)
    rebate = min(z, b["annualTax"])
    outs = [b["epf"], b["erEpf"], b["socso"], b["erSocso"], b["eis"], b["erEis"], b["annualTax"], b["pcb"],
            b["takeHome"], b["employerCost"], z, v1.sen(z / 12), rebate, z - rebate]
    ins = [sen(salary), age, year, STATUSES.index(status), children, int(opted_out), int(wife)]
    return [ins, [sen(x) for x in outs]]


cases = []
# 1. Sweep: every RM100 from RM1,700 to RM30,000, age 30, single, 2026 defaults.
for g in range(1700, 30001, 100):
    cases.append(case(g, 30, 2026, "single", 0, False, False))

# 2. Boundaries crossed with age, year, status, children, SKBBK opt-out and wife deduction.
SALARIES = [5, 10, 10.01, 500, 1500, 1700, 1700.01, 2000, 3000, 3445, 3500, 4000, 4000.01, 4001,
            4045, 4309, 4334, 4500, 5000, 5000.01, 5001, 5900, 5900.01, 6000, 6000.01, 7000, 8000,
            9000, 10000, 12000, 15000, 19999.99, 20000, 20000.01, 25000, 50000, 100000]
FAMILIES = [("single", 0, False), ("single", 2, False), ("married-spouse-working", 0, False),
            ("married-spouse-working", 2, True), ("married-spouse-not-working", 0, True),
            ("married-spouse-not-working", 3, False), ("divorced-or-widowed", 1, False)]
for g in SALARIES:
    for age in (17, 30, 59, 60, 75):
        for year in (2025, 2026, 2027):
            for status, kids, wife in FAMILIES:
                for opted in ((False,) if year == 2025 else (False, True)):
                    cases.append(case(g, age, year, status, kids, opted, wife))

out = {
    "$comment": "Generated by tests/fixtures/generate_golden.py from docs/research/data/v1-baseline.py. Do not edit by hand. Amounts in sen.",
    "statuses": STATUSES,
    "inputs": INPUTS,
    "outputs": OUTPUTS,
    "cases": cases,
}
path = os.path.join(os.path.dirname(__file__), "golden.json")
with open(path, "w") as f:
    json.dump(out, f, separators=(",", ":"))
    f.write("\n")
print(f"wrote {len(cases)} cases to {path}")
